INSERT INTO changelog (title, body, created_at) VALUES ('AI-радар працює у фоні', 'Прогін радару триває 3–7 хв (пошук по вебу), і кнопка «Перевірити зараз» падала з помилкою, хоча радар доробляв. Тепер запуск іде у фоні: кнопка показує «Джері шукає…», сторінка сама оновлюється, нове приходить у Telegram. Можна піти зі сторінки. Перший прогін 07.11 дав 4 картки.', datetime('now'));
